import{_ as t,o as s,c as r,a0 as a}from"./chunks/framework.D4fUSYzX.js";const m=JSON.parse(`{"title":"ADR 0053: The review score read takes the pull request's comments and its reviews","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0053-the-review-score-read-takes-the-pull-requests-comments-and-its-reviews.md","filePath":"adr/0053-the-review-score-read-takes-the-pull-requests-comments-and-its-reviews.md"}`),o={name:"adr/0053-the-review-score-read-takes-the-pull-requests-comments-and-its-reviews.md"};function i(n,e,d,h,c,l){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0053-the-review-score-read-takes-the-pull-request-s-comments-and-its-reviews" tabindex="-1">ADR 0053: The review score read takes the pull request&#39;s comments and its reviews <a class="header-anchor" href="#adr-0053-the-review-score-read-takes-the-pull-request-s-comments-and-its-reviews" aria-label="Permalink to &quot;ADR 0053: The review score read takes the pull request&#39;s comments and its reviews&quot;">​</a></h1><p>Status: accepted Date: 2026-09-22</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A transition branch tests a judgment (ADR 0027): the review score against the configured threshold. The score judgment reads the verdict live at the settle (ADR 0047): the plane issues one REST read of the pull request&#39;s issue comments through the command runner, and the judgment decides on the newest comment that carries the template&#39;s fixed score line.</p><p>The read took one posting path, and a review agent chose the other. A real review turn on <code>SeriousJul/pi-extensions</code> PR #97 scored the pull request 97/100 and posted the verdict as a pull request <strong>review</strong> (<code>gh pr review</code>), not as an issue comment. The settle&#39;s comment read found zero comments, the score read answered null, neither score branch held, and the transition recorded its no-fire: the pull request never wore <code>ready-to-ship</code>, the machine offered no merge, and the ticket sat in <code>awaiting</code> on a turn whose verdict the plane could see but could not read. A no-fire records nothing the re-fire sweep re-fires (the sweep is bounded to the missing-pull-request skip, ADR 0042), so the record stood until a human re-drove the cycle.</p><p>Both paths are on the record: a comment posts to the pull request&#39;s issue timeline, and a review body posts to its review timeline. The template&#39;s fixed line is the contract, and it stands in either body.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>**The score read collects the verdict records of both posting timelines</p><ul><li>the pull request&#39;s issue comments and its review bodies - and takes the newest record that carries the template&#39;s fixed score line.** The fire issues the two reads together, each with the source&#39;s host and the resolved auth, gated like the score read: a transition that tests no score judgment issues no read of either timeline.</li></ul><p><strong>Each read fails open on its own timeline.</strong> A read that fails, or answers a list it cannot read, contributes no records, and the records that stand decide. The score is null only when no standing record carries the fixed line.</p><p><strong>The shipped review template&#39;s Outcome line names both paths.</strong> The agent posts its output on the pull request, as a comment or a review, and the plane reads both. The fixed line and the newest-record rule are unchanged: the newest record across both timelines is the verdict.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A verdict posted through a review decides the judgment: the no-fire on a review-posted score is gone, and the turn that posted it routes the pull request to its state the way a comment-posted verdict does.</li><li>A failed read on one timeline no longer voids the verdict on the other: the comment read that fails with the reviews standing still decides on the reviews, and the reverse.</li><li>The fire&#39;s settle gains one read, gated like the read it joins: no branch that tests a score, no read of either timeline.</li><li>The newest-record rule is across timelines: a comment and a review order by their timestamps, and the later one is the verdict, whatever the timeline it posted to.</li><li>The template&#39;s Outcome line changes on shipped installs: an existing config keeps its own review template untouched, and the migration replaces only a seed-matched template, so no install&#39;s review prompt changes without its operator&#39;s hand.</li></ul>',13)])])}const p=t(o,[["render",i]]);export{m as __pageData,p as default};
